import { writeFile } from "node:fs/promises";
import { generateSpeech } from "ai";
import { readaloud } from "ai-sdk-provider-readaloud";

const { audio, warnings, providerMetadata } = await generateSpeech({
  model: readaloud.speech(),
  text: "Thanks for calling. How can I help you today?",
  voice: "readaloud-default",
  outputFormat: "mp3",
});
await writeFile("vercel_out.mp3", audio.uint8Array);
console.log(audio.mediaType, audio.uint8Array.length, "bytes", JSON.stringify(warnings), JSON.stringify(providerMetadata));
